1	export type Cell = [number, number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isAdjacent([x, y]: Cell, [otherX, otherY]: Cell): boolean {
8	  return Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
9	}
10	
11	function isNeighbor(cell: Cell, other: Cell): boolean {
12	  return isAdjacent(cell, other) && !isSameCell(cell, other);
13	}
14	
15	function liveNeighborCount(cell: Cell, liveCells: Cell[]): number {
16	  return liveCells.filter((other) => isNeighbor(cell, other)).length;
17	}
18	
19	export function nextGeneration(liveCells: Cell[]): Cell[] {
20	  return liveCells.filter((cell) => {
21	    const neighbors = liveNeighborCount(cell, liveCells);
22	    return neighbors >= 2 && neighbors <= 3;
23	  });
24	}
