4	describe("Game of Life - Next Generation", () => {
5	  it("returns an empty grid for an empty grid — [] → []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("kills a single live cell with no neighbors — [(0,0)] → []", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("kills two live cells that each have 1 neighbor (underpopulation) — [(0,1), (1,1)] → []", () => {
12	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
13	  });
14	  // NOTE: the spec's Rule 2 illustration is internally inconsistent — its diagram
